/// <summary>
/// Extension class for InventTransferShipReceiveController
/// </summary>
[ExtensionOf(classStr(InventTransferShipReceiveController))]
final class METInventTransferShipReceiveController_Extension
{
}

Method.Source:
/// <summary>
/// Setting up additional ranges incase called from Shipment. 
/// </summary>
/// <param name = "_query">Query reference</param>
public void setRanges(Query _query)
{
    next setRanges(_query);

    if (this.parmArgs().record() is metSalesOrderShipmentLoadHeader)
    {
        this.parmShowDialog(false);
        metSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
        FormRun     formRun = this.parmArgs().caller();
        Map         map = formRun.getFinalizationHeaderMap();
        MapIterator mapIterator;
        InventTransferJour  inventTransferJour;

        mapIterator = new MapIterator (map);

        QueryBuildDataSource queryBuildDataSource = _query.dataSourceTable(tableNum(InventTransferJour));

        QueryBuildRange qbrTransferId = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(InventTransferJour, TransferId));
        QueryBuildRange qbrVoucherId  = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(InventTransferJour, VoucherId));
        QueryBuildRange qbrTransDate  = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(InventTransferJour, TransDate));

        while (mapIterator.more())
        {
            metSalesOrderShipmentLoadHeader = metSalesOrderShipmentLoadHeader::findByRecId(mapIterator.key(), true);

            ///Nested while needed to club all transfer order Ids for the shipment. 
            while select TransferId, VoucherId, TransDate from inventTransferJour
                where inventTransferJour.METShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId    &&
                    inventTransferJour.METLoadId == metSalesOrderShipmentLoadHeader.LoadId
            {
                qbrTransferId.value(queryValue(inventTransferJour.TransferId));
                qbrVoucherId.value(queryValue(inventTransferJour.VoucherId));
                qbrTransDate.value(queryValue(inventTransferJour.TransDate));
            }

            mapIterator.next();
        }
    }
}
